class _CentinelaFilter(logging.Filter):
    """Pasa TODO lo del logger 'centinela'; del resto solo WARNING+.
    Evita que websockets/PIL/asyncio escriban en disco a nivel DEBUG.
    """
    def filter(self, record):
        return record.name == 'centinela' or record.levelno >= logging.WARNING


def _setup_logging():
    log_dir = os.path.join(
        os.environ.get("PROGRAMDATA", os.environ.get("APPDATA", os.path.dirname(os.path.abspath(__file__)))),
        "ApolloSupport"
    )
    os.makedirs(log_dir, exist_ok=True)
    log_file = os.path.join(log_dir, "centinela.log")

    fmt = logging.Formatter("%(asctime)s [%(levelname)s] %(message)s", datefmt="%Y-%m-%d %H:%M:%S")
    _f = _CentinelaFilter()

    # RotaciÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n diaria, guarda 7 dÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â­as
    fh = logging.handlers.TimedRotatingFileHandler(log_file, when="midnight", backupCount=7, encoding="utf-8")
    fh.setFormatter(fmt)
    fh.addFilter(_f)

    # Consola (ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âºtil al ejecutar manualmente)
    ch = logging.StreamHandler()
    ch.setFormatter(fmt)
    ch.addFilter(_f)

    root = logging.getLogger()
    root.setLevel(logging.DEBUG)  # dejar todo pasar ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â el Filter hace el filtrado real
    root.addHandler(fh)
    root.addHandler(ch)

    return log_file


_LOG_FILE = _setup_logging()
