# --- Update check (companion UI) ---
_UPDATE_INFO = {"available": False, "version": "", "url": "", "busy": False, "notes": ""}


def _parse_version(v_str):
    parts = []
    for x in str(v_str or "0").split("."):
        digits = ""
        for ch in x:
            if ch.isdigit():
                digits += ch
            elif digits:
                break
        if digits:
            parts.append(int(digits))
    return parts or [0]


def _api_http_base():
    return BASE_WS_URL.replace("wss://", "https://").replace("ws://", "http://").split("/api/ws")[0]


def _preferred_arch():
    return "x64" if ctypes.sizeof(ctypes.c_void_p) == 8 else "x86"


def fetch_remote_update():
    """Si el servidor tiene una version mayor, devuelve {version, url, notes}. Si no, None."""
    check_url = f"{_api_http_base()}/api/centinela/update_check"
    r = requests.get(check_url, timeout=12, headers={"User-Agent": "ApolloCentinela"})
    r.raise_for_status()
    data = r.json() if r.content else {}
    remote = str(data.get("version") or "0.0.0")
    if _parse_version(remote) <= _parse_version(CLIENT_VERSION):
        return None
    downloads = data.get("downloads") or {}
    dl = downloads.get(_preferred_arch()) or downloads.get("combined") or {}
    dl_url = (dl.get("url") or data.get("url") or "").strip()
    if dl_url.startswith("/"):
        dl_url = _api_http_base() + dl_url
    if not dl_url:
        return None
    return {"version": remote, "url": dl_url, "notes": data.get("notes") or ""}

def get_alt_remote_id():
    import os, re
    # Check RustDesk
    dirs = [
        os.path.join(os.environ.get("APPDATA", ""), "RustDesk", "config"),
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "RustDesk", "config"),
        r"C:\Windows\System32\config\systemprofile\AppData\Roaming\RustDesk\config",
        r"C:\Windows\SysWOW64\config\systemprofile\AppData\Roaming\RustDesk\config"
    ]
    filenames = ["RustDesk.toml", "RustDesk_local.toml", "rustdesk.toml", "RustDesk2.toml"]
    
    rustdesk_paths = []
    for d in dirs:
        for f in filenames:
            rustdesk_paths.append(os.path.join(d, f))
            
    for p in rustdesk_paths:
        if p and os.path.exists(p):
            try:
                with open(p, "r", encoding="utf-8") as f:
                    for line in f:
                        if line.strip().startswith("id ="):
                            m = re.search(r"id\s*=\s*'([^']+)'", line)
                            if m: return m.group(1)
            except: pass
            
    # Check AnyDesk
    anydesk_paths = [
        os.path.join(os.environ.get("ProgramData", "C:\\ProgramData"), "AnyDesk", "system.conf"),
        os.path.join(os.environ.get("APPDATA", ""), "AnyDesk", "system.conf")
    ]
    for p in anydesk_paths:
        if p and os.path.exists(p):
            try:
                with open(p, "r", encoding="utf-8") as f:
                    for line in f:
                        if line.startswith("ad.anynet.id="):
                            return line.split("=")[1].strip()
            except: pass
    return ""

def get_current_session_id():
    """Retorna el ID de sesiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n Windows del proceso actual."""
    try:
        import ctypes
        pid = os.getpid()
        session_id = ctypes.c_ulong(0)
        ctypes.windll.kernel32.ProcessIdToSessionId(pid, ctypes.byref(session_id))
        return session_id.value
    except Exception:
        return 1  # Asumir sesiÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â³n 1 si no podemos detectarla

